WITH closed AS (
  SELECT County, School, ClosedDate FROM schools WHERE StatusType = 'Closed'
),
top AS (
  SELECT County FROM closed GROUP BY County ORDER BY COUNT(*) DESC LIMIT 1
)
SELECT c.County, c.School, c.ClosedDate
FROM closed c
JOIN top t ON c.County = t.County
ORDER BY c.ClosedDate;
